36	/**
37	 * List user's linked OAuth accounts
38	 */
39	credentialRoutes.get('/accounts', requireAuth, async (c) => {
40	  const user = getAuthenticatedUser(c);
41	  const sql = createDbClientFromEnv(c.env);
42	
43	  const result = await sql`
44	    SELECT
45	      id,
46	      "accountId",
47	      "providerId",
48	      "accessToken" IS NOT NULL as "hasAccessToken",
49	      "refreshToken" IS NOT NULL as "hasRefreshToken",
50	      "accessTokenExpiresAt",
51	      scope,
52	      "createdAt"
53	    FROM "account"
54	    WHERE "userId" = ${user.id}
55	    ORDER BY "createdAt" DESC
56	  `;
57	  return c.json({ accounts: result });
58	});
