61	// OAuth Agents Routes
62	// ============================================
63	
64	/**
65	 * List OAuth agents (clients) for an organization
66	 */
67	credentialRoutes.get('/agents', requireAuth, async (c) => {
68	  const user = getAuthenticatedUser(c);
69	  const orgSlug = c.req.query('org_slug');
70	
71	  const sql = createDbClientFromEnv(c.env);
72	
73	  let organizationId: string;
74	
75	  if (orgSlug) {
76	    const membership = await sql`
77	      SELECT m."organizationId" as organization_id
78	      FROM "member" m
79	      JOIN "organization" o ON o.id = m."organizationId"
80	      WHERE m."userId" = ${user.id}
81	        AND o.slug = ${orgSlug}
82	      LIMIT 1
83	    `;
84	    if (membership.length === 0) {
85	      return c.json({ error: `Not a member of organization '${orgSlug}'` }, 403);
86	    }
87	    organizationId = membership[0].organization_id as string;
88	  } else {
89	    // Fall back to user's first org membership
90	    const defaultOrg = await sql`
91	      SELECT m."organizationId" as organization_id
92	      FROM "member" m
93	      WHERE m."userId" = ${user.id}
94	      ORDER BY m."createdAt" ASC
95	      LIMIT 1
96	    `;
97	    if (defaultOrg.length === 0) {
98	      return c.json({ error: 'No organization membership found' }, 404);
99	    }
100	    organizationId = defaultOrg[0].organization_id as string;
101	  }
102	  const clientsStore = new OAuthClientsStore(sql);
103	  const agents = await clientsStore.listClientsByOrganization(organizationId);
104	
105	  return c.json({ agents });
106	});
