108	// ============================================
109	// Org-scoped Personal Access Token Routes
110	// ============================================
111	
112	// Mintable PAT scopes + default scope live in oauth/scopes.ts — the single
113	// source of truth for scope definitions.
114	const AVAILABLE_PAT_SCOPE_SET = new Set<string>(AVAILABLE_PAT_SCOPES);
115	const DEFAULT_PAT_SCOPE = DEFAULT_SCOPES_STRING;
116	const MAX_PAT_EXPIRY_DAYS = 3650;
117	
118	function authorizeTokenCreation(c: Context<{ Bindings: Env }>) {
119	  const user = c.get('user');
120	  if (!user?.id) {
121	    return { error: c.json({ error: 'Unauthorized', message: 'Authentication required' }, 401) };
122	  }
123	
124	  const organizationId = c.get('organizationId');
125	  if (!organizationId) {
126	    return { error: c.json({ error: 'Organization slug is required in URL' }, 400) };
127	  }
128	
129	  const role = c.get('memberRole');
130	  if (role !== 'owner' && role !== 'admin') {
131	    return { error: c.json({ error: 'Token creation requires org owner or admin access' }, 403) };
132	  }
133	
134	  const authSource = c.get('authSource');
135	  if (authSource === 'pat') {
136	    return {
137	      error: c.json(
138	        { error: 'Use `lobu login` with OAuth or a web session to create server tokens' },
139	        403
140	      ),
141	    };
142	  }
143	
144	  const scopes = c.get('mcpAuthInfo')?.scopes ?? [];
145	  if (authSource === 'oauth' && !scopes.includes('mcp:admin')) {
146	    return { error: c.json({ error: 'Token creation requires mcp:admin scope' }, 403) };
147	  }
148	
149	  return { user, organizationId };
150	}
151	
152	function normalizePatScope(scope: unknown): string | undefined {
153	  if (scope === undefined || scope === null || scope === '') return DEFAULT_PAT_SCOPE;
154	  if (typeof scope !== 'string') {
155	    throw new Error('scope must be a space-separated string');
156	  }
157	  const scopes = Array.from(new Set(scope.split(/\s+/).map((value) => value.trim()).filter(Boolean)));
158	  if (scopes.length === 0) return DEFAULT_PAT_SCOPE;
159	  const invalid = scopes.filter((value) => !AVAILABLE_PAT_SCOPE_SET.has(value));
160	  if (invalid.length > 0) {
161	    throw new Error(`Invalid scope(s): ${invalid.join(', ')}`);
162	  }
163	  return scopes.join(' ');
164	}
165	
166	function normalizeExpiryDays(value: unknown): number | undefined {
167	  if (value === undefined || value === null || value === '') return undefined;
168	  const days = Number(value);
169	  if (!Number.isInteger(days) || days < 1 || days > MAX_PAT_EXPIRY_DAYS) {
170	    throw new Error(`expiresInDays must be an integer between 1 and ${MAX_PAT_EXPIRY_DAYS}`);
171	  }
172	  return days;
173	}
174	
