1	import { describe, expect, test } from "bun:test";
2	import {
3		SESSION_COOKIE_BASENAME,
4		convergeSetCookieScope,
5		countNamedCookies,
6		hostOnlyExpiry,
7		sessionCookieName,
8	} from "../../auth/session-cookie-scope";
9	
10	/**
11	 * Regression cover for the permanent-login-brick class.
12	 *
13	 * Two cookies can carry the same name at different scopes — host-only
14	 * (`app.lobu.ai`) and domain-scoped (`Domain=.lobu.ai`). The browser sends
15	 * BOTH, the server takes the FIRST, and RFC 6265 §5.4 orders equal-path
16	 * cookies oldest-first. So once a stale host-only session cookie exists, every
17	 * later sign-in writes a strictly NEWER cookie that can never win, and the
18	 * user is locked out with no in-app escape — re-logging-in cannot fix it.
19	 *
20	 * Measured against prod 2026-08-06 (`/api/auth/get-session`, correctly signed):
21	 *   good        -> session
22	 *   dead        -> null
23	 *   dead; good  -> null      <- the brick
24	 *   good; dead  -> session
25	 *
26	 * The fix makes sign-in authoritative: whenever a response sets a
27	 * domain-scoped cookie, it must also expire the host-only twin of that name.
28	 */
29	describe("session cookie scope convergence", () => {
30		test("names the cookie the way Better Auth does", () => {
31			expect(sessionCookieName(true)).toBe(`__Secure-${SESSION_COOKIE_BASENAME}`);
32			expect(sessionCookieName(false)).toBe(SESSION_COOKIE_BASENAME);
33		});
34	
35		test("counts duplicate session cookies in a Cookie header (the brick signal)", () => {
36			const name = sessionCookieName(true);
37			expect(countNamedCookies("", name)).toBe(0);
38			expect(countNamedCookies(`${name}=good`, name)).toBe(1);
39			expect(countNamedCookies(`${name}=dead; ${name}=good`, name)).toBe(2);
40			// A different cookie that merely shares a prefix must not be counted.
41			expect(countNamedCookies(`${name}_other=x; ${name}=good`, name)).toBe(1);
42			// The unprefixed name must not match the __Secure- variant.
43			expect(countNamedCookies(`__Secure-${name}=x`, name)).toBe(0);
44		});
45	
46		test("builds a host-only expiry that targets the twin, never the domain cookie", () => {
47			const header = hostOnlyExpiry(sessionCookieName(true), true);
48			expect(header).toMatch(/^__Secure-better-auth\.session_token=;/);
49			expect(header).toMatch(/Max-Age=0/);
50			expect(header).toMatch(/Path=\//);
51			expect(header).toMatch(/Secure/);
52			// Load-bearing: no Domain attribute => deletes ONLY the host-only cookie.
53			expect(header).not.toMatch(/Domain=/i);
54		});
55	
56		test("appends a host-only expiry for every domain-scoped cookie it sets", () => {
57			const name = sessionCookieName(true);
58			const out = convergeSetCookieScope(
59				[`${name}=abc.sig; Domain=.lobu.ai; Path=/; HttpOnly; Secure; SameSite=Lax`],
60				{ cookieDomain: ".lobu.ai", isHttps: true },
61			);
62			expect(out).toHaveLength(2);
63			expect(out[0]).toContain("Domain=.lobu.ai");
64			expect(out[1]).toBe(hostOnlyExpiry(name, true));
65		});
66	
67		test("covers the OAuth state/pkce cookies too — a shadowed state breaks the callback", () => {
68			const out = convergeSetCookieScope(
69				[
70					"__Secure-better-auth.state=s1; Domain=.lobu.ai; Path=/; HttpOnly; Secure",
71					"__Secure-better-auth.pkce_code_verifier=v1; Domain=.lobu.ai; Path=/; HttpOnly; Secure",
72				],
73				{ cookieDomain: ".lobu.ai", isHttps: true },
74			);
75			expect(out).toHaveLength(4);
76			expect(out.filter((h) => h.includes("Max-Age=0"))).toHaveLength(2);
77			expect(out.some((h) => h.startsWith("__Secure-better-auth.state=;"))).toBe(
78				true,
79			);
80			expect(
81				out.some((h) => h.startsWith("__Secure-better-auth.pkce_code_verifier=;")),
82			).toBe(true);
83		});
84	
85		test("mirrors the source cookie's Secure even when https detection disagrees", () => {
86			// Better Auth keys `useSecureCookies` on NODE_ENV/configured origin, not
87			// on this request's forwarded proto. A Secure-less expiry for a
88			// `__Secure-` name is silently rejected by the browser — the twin
89			// survives and the convergence no-ops.
90			const name = sessionCookieName(true);
91			const out = convergeSetCookieScope(
92				[`${name}=abc.sig; Domain=.lobu.ai; Path=/; HttpOnly; Secure; SameSite=Lax`],
93				{ cookieDomain: ".lobu.ai", isHttps: false },
94			);
95			expect(out).toHaveLength(2);
96			expect(out[1]).toMatch(/;\s*Secure$/);
97		});
98	
99		test("is a no-op with no cookie zone (local dev: host-only IS the real cookie)", () => {
100			const name = sessionCookieName(false);
101			const set = [`${name}=abc.sig; Path=/; HttpOnly; SameSite=Lax`];
102			expect(
103				convergeSetCookieScope(set, { cookieDomain: undefined, isHttps: false }),
104			).toEqual(set);
105		});
106	
107		test("never re-expires a cookie the response is already deleting", () => {
108			const name = sessionCookieName(true);
109			const set = [`${name}=; Domain=.lobu.ai; Path=/; Max-Age=0`];
110			expect(
111				convergeSetCookieScope(set, { cookieDomain: ".lobu.ai", isHttps: true }),
112			).toEqual(set);
113		});
114	
115		test("leaves host-only Set-Cookies alone (nothing to converge)", () => {
116			const set = ["lobu_settings_session=abc; Path=/; HttpOnly; SameSite=Lax"];
117			expect(
118				convergeSetCookieScope(set, { cookieDomain: ".lobu.ai", isHttps: true }),
119			).toEqual(set);
120		});
121	});

1	/**
2	 * Cookie-scope convergence for the Better Auth session cookie.
3	 *
4	 * The same cookie name can exist at two scopes at once — host-only
5	 * (`app.lobu.ai`) and domain-scoped (`Domain=.lobu.ai`). A browser sends BOTH
6	 * in one `Cookie` header, the server resolves the FIRST, and RFC 6265 §5.4
7	 * orders equal-path cookies oldest-first. A stale host-only session cookie is
8	 * therefore permanently unbeatable: every later sign-in writes a strictly
9	 * NEWER cookie that can never take precedence, so the user is locked out of
10	 * the app with no in-app way to recover. Measured on prod 2026-08-06 —
11	 * `dead; good` resolves to `null` while `good; dead` resolves to the session.
12	 *
13	 * Host-only twins are produced by any path that sets the session cookie
14	 * without the configured zone: the `/exchange-token` and `/local-init` deep
15	 * links used to, and `document.cookie` planting (see docs/BROWSER_TESTING.md)
16	 * still can.
17	 *
18	 * The cure is to make sign-in authoritative. Whenever a response sets a
19	 * domain-scoped auth cookie, it also expires the host-only twin of that same
20	 * name, so a single sign-in collapses the jar back to one cookie — which also
21	 * self-heals an already-bricked browser on its next sign-in.
22	 */
23	
24	/** Better Auth's session cookie name, before the `__Secure-` prefix. */
25	export const SESSION_COOKIE_BASENAME = "better-auth.session_token";
26	
27	/**
28	 * Better Auth adds the `__Secure-` prefix whenever it issues secure cookies
29	 * (`useSecureCookies` in auth/index.tsx: NODE_ENV production, or an https
30	 * configured public origin). Derive the name from the resolved public origin —
31	 * TLS is often terminated by a reverse proxy, so the bind speaking plain HTTP
32	 * says nothing about the name the browser actually holds.
33	 */
34	export function sessionCookieName(isHttps: boolean): string {
35		return isHttps ? `__Secure-${SESSION_COOKIE_BASENAME}` : SESSION_COOKIE_BASENAME;
36	}
37	
38	/**
39	 * Count how many times `name` appears in a `Cookie` request header.
40	 *
41	 * More than one is the brick signature: the request carries the same cookie at
42	 * two scopes and the loser is invisible to every log we keep. Matching is on
43	 * the exact name before `=`, so neither a `<name>_other` cookie nor a
44	 * `__Secure-<name>` cookie is mistaken for `<name>`.
45	 */
46	export function countNamedCookies(
47		cookieHeader: string | null | undefined,
48		name: string,
49	): number {
50		if (!cookieHeader) return 0;
51		let count = 0;
52		for (const part of cookieHeader.split(";")) {
53			const eq = part.indexOf("=");
54			if (eq === -1) continue;
55			if (part.slice(0, eq).trim() === name) count += 1;
56		}
57		return count;
58	}
59	
60	/**
61	 * A `Set-Cookie` value that deletes the HOST-ONLY cookie called `name`.
62	 *
63	 * Deliberately carries no `Domain` attribute: cookie deletion matches on
64	 * (name, domain, path), so omitting Domain targets the host-only twin and
65	 * leaves the domain-scoped cookie — the one we actually want the browser to
66	 * keep — untouched. `Secure` is mandatory rather than cosmetic: a browser
67	 * rejects any `Set-Cookie` for a `__Secure-`-prefixed name that lacks it, so
68	 * without it the deletion would silently no-op.
69	 */
70	export function hostOnlyExpiry(name: string, secure: boolean): string {
71		const parts = [`${name}=`, "Path=/", "Max-Age=0", "HttpOnly", "SameSite=Lax"];
72		if (secure) parts.push("Secure");
73		return parts.join("; ");
74	}
75	
76	/** True when this `Set-Cookie` is itself a deletion — nothing to converge. */
77	function isExpiry(setCookie: string): boolean {
78		return /;\s*Max-Age=0\b/i.test(setCookie) || /;\s*Expires=Thu, 01 Jan 1970/i.test(setCookie);
79	}
80	
81	/**
82	 * Given the `Set-Cookie` headers a response is about to send, append a
83	 * host-only expiry for every cookie it sets with a `Domain` attribute.
84	 *
85	 * No-ops when no zone is configured: in local dev the host-only cookie IS the
86	 * real session cookie, and expiring it would log the developer out on sign-in.
87	 */
88	export function convergeSetCookieScope(
89		setCookies: string[],
90		opts: { cookieDomain?: string; isHttps: boolean },
91	): string[] {
92		if (!opts.cookieDomain) return setCookies;
93	
94		const out = [...setCookies];
95		const expired = new Set<string>();
96		for (const setCookie of setCookies) {
97			const eq = setCookie.indexOf("=");
98			if (eq === -1) continue;
99			const name = setCookie.slice(0, eq).trim();
100			if (!name || expired.has(name)) continue;
101			// Only a domain-scoped Set-Cookie can be shadowed by a host-only twin.
102			if (!/;\s*Domain=/i.test(setCookie)) continue;
103			if (isExpiry(setCookie)) continue;
104			expired.add(name);
105			// Mirror the source cookie's Secure, not just our own https detection:
106			// Better Auth decides `useSecureCookies` from NODE_ENV/configured origin,
107			// not from this request's forwarded proto. If it issued a `__Secure-`
108			// cookie, an expiry without Secure is silently rejected — the exact
109			// no-op this module exists to prevent.
110			const secure = opts.isHttps || /;\s*Secure\s*(;|$)/i.test(setCookie);
111			out.push(hostOnlyExpiry(name, secure));
112		}
113		return out;
114	}
115	
116	/**
117	 * Rewrite a Response's `Set-Cookie` headers in place so every domain-scoped
118	 * auth cookie it sets also expires its host-only twin.
119	 *
120	 * Applied at the `/api/auth/*` chokepoint, this covers every sign-in method at
121	 * once — Google, Slack, magic link, credential, passkey — plus the `state` and
122	 * `pkce_code_verifier` cookies, where a shadowed value breaks the OAuth
123	 * callback rather than the session.
124	 */
125	export function convergeResponseCookieScope(
126		response: Response,
127		opts: { cookieDomain?: string; isHttps: boolean },
128	): Response {
129		if (!opts.cookieDomain) return response;
130		const existing = response.headers.getSetCookie();
131		if (existing.length === 0) return response;
132	
133		const converged = convergeSetCookieScope(existing, opts);
134		if (converged.length === existing.length) return response;
135	
136		response.headers.delete("set-cookie");
137		for (const value of converged) response.headers.append("set-cookie", value);
138		return response;
139	}

